    public function savePrivacy(int$actor,array$d):void{[, $u]=$this->context($actor);$uid=(int)$u['user_id'];DB::table('users')->where('user_id',$uid)->update(['visibility'=>!empty($d['showPublicProfile'])?'public':'private','updated_by'=>$actor]);foreach(['privacy_show_branches'=>'showBranches','privacy_show_teachers'=>'showTeachers','privacy_show_contact'=>'showContact','privacy_show_stats'=>'showStats','privacy_indexable'=>'indexable']as$key=>$field)$this->setSetting($uid,$key,!empty($d[$field])?'1':'0',$actor);}
    public function saveSecurity(int$actor,array$d):void{[, $u]=$this->context($actor);$uid=(int)$u['user_id'];$values=['email'=>$this->email($d['email']??null),'phone'=>$this->phone($d['phone']??null),'updated_by'=>$actor];$password=(string)($d['password']??'');if($password!==''){if(strlen($password)<8)throw new RuntimeException('رمز عبور باید حداقل ۸ کاراکتر باشد.');if(!hash_equals($password,(string)($d['passwordConfirmation']??'')))throw new RuntimeException('تکرار رمز عبور مطابقت ندارد.');$values['password']=password_hash($password,PASSWORD_DEFAULT);}DB::table('users')->where('user_id',$uid)->update($values);if($password!=='')$this->securityEvent($actor,'password_changed','رمز عبور حساب آموزشگاه تغییر کرد.');}
