    private function context(int $actor):array{$current=DB::table('users')->where('user_id',$actor)->whereNull('deleted_at')->first();if(!$current)throw new RuntimeException('حساب کاربری یافت نشد.');$branch=$this->branchContext($actor);$academy=$branch?DB::table('academies')->where('academy_id',(int)$branch['academy_id'])->whereNull('deleted_at')->first():(DB::table('academies')->where('user_id',$actor)->whereNull('deleted_at')->first()?:DB::table('academies')->where('created_by',$actor)->whereNull('deleted_at')->orderBy('academy_id')->first());if(!$academy&&SiteAdminAccess::allows($current))$academy=DB::table('academies')->whereNull('deleted_at')->orderBy('academy_id')->first();return[$academy?:['academy_id'=>0,'created_by'=>$actor],$current];}
