    private function documents(int$aid,string$locale):array{$rows=db()->prepare('SELECT d.*,m.* FROM academy_documents d JOIN media_files m ON m.media_file_id=d.media_file_id AND m.deleted_at IS NULL WHERE d.academy_id=? AND d.deleted_at IS NULL ORDER BY d.academy_document_id DESC');$rows->execute([$aid]);return array_map(fn($r)=>['id'=>(int)$r['media_file_id'],'documentId'=>(int)$r['academy_document_id'],'name'=>$r['original_filename']?:$r['filename'],'size'=>$this->size((int)$r['size']),'date'=>$r['created_at'],'type'=>$r['type'],'documentType'=>$r['document_type'],'number'=>$r['document_number'],'issuedAt'=>$r['issued_at'],'expiresAt'=>$r['expires_at'],'status'=>$r['status'],'url'=>'/analytics/admin-account/media/'.(int)$r['media_file_id'].'/download'],$rows->fetchAll());}
