    private function securityAlerts(int$uid):array{$q=db()->prepare("SELECT * FROM tracking_user_events WHERE user_id=? AND event_name IN ('login_failed','password_changed','network_offline') ORDER BY occurred_at DESC LIMIT 30");$q->execute([$uid]);return array_map(fn($r)=>['id'=>(int)$r['tracking_user_event_id'],'level'=>$r['event_name']==='login_failed'?'danger':'info','title'=>$r['event_name']==='login_failed'?'تلاش ورود ناموفق':($r['event_name']==='password_changed'?'تغییر رمز عبور':'قطع اتصال شبکه'),'text'=>$r['event_label']?:'این رویداد توسط سامانه ثبت شده است.','date'=>$r['occurred_at']],$q->fetchAll());}
