    private function securityEvent(int$uid,string$name,string$label):void{$s=DB::table('tracking_user_sessions')->where('user_id',$uid)->orderBy('tracking_user_session_id','DESC')->first();if(!$s)return;$p=DB::table('tracking_user_page_views')->where('tracking_user_session_id',(int)$s['tracking_user_session_id'])->orderBy('tracking_user_page_view_id','DESC')->first();if(!$p)return;$sequence=(int)(db()->query('SELECT COALESCE(MAX(sequence_number),0)+1 FROM tracking_user_events WHERE page_view_id='.(int)$p['tracking_user_page_view_id'])->fetchColumn());$uuid=sprintf('%s-%s-4%s-%s%s-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),substr(bin2hex(random_bytes(2)),1),dechex(random_int(8,11)),substr(bin2hex(random_bytes(2)),1),bin2hex(random_bytes(6)));DB::table('tracking_user_events')->insert(['event_uuid'=>$uuid,'tracking_user_session_id'=>(int)$s['tracking_user_session_id'],'user_id'=>$uid,'page_view_id'=>(int)$p['tracking_user_page_view_id'],'sequence_number'=>$sequence,'event_name'=>$name,'event_category'=>'security','event_action'=>$name,'event_label'=>$label,'occurred_at'=>date('Y-m-d H:i:s.v'),'client_timestamp_ms'=>(int)(microtime(true)*1000),'event_version'=>1,'source'=>'server','event_data'=>'{}','page_url'=>$p['page_url']]);}
